  async function scanTank(){const raw=await scanQrCode({title:'Maschinentank scannen',help:'Erwartet wird nur der Tank-Lagerort, z. B. EOS1.'});const code=String(raw||'').trim();if(!code||code.includes('+++'))throw new Error('Ungültiger Maschinentank-QR.');await loadMachines();const m=machines.find(x=>String(x.warehouse).toUpperCase()===code.toUpperCase());if(!m)throw new Error(`Lagerort ${code} ist in Oxaion nicht als Tanklagerort (Lagerortart 02) definiert.`);const r=await api('/api/machines/'+encodeURIComponent(m.warehouse)+'/stock');if(!r.ok)throw new Error(r.body?.detail||r.body?.message||r.body?.error||'Tankbestand konnte nicht gelesen werden.');return{machine:m,stock:r.body};}

  function outWeighed(){const s=String(el('outWeighedAmount')?.value||'').trim();if(!s)return null;const n=Number(s.replace(',','.'));return Number.isFinite(n)?Math.round(n*1000)/1000:NaN}
